export const PEPTIDE_CATEGORIES = [
  'Metabolic/Weight',
  'Healing/Recovery',
  'GH Axis',
  'Muscle/Performance',
  'Longevity',
  'Cognition/Mood',
  'Sleep',
  'Immune/Anti-inf',
  'Skin/Hair',
  'Sexual Health',
  'Cardio/Vascular',
  'GI/Bone/Other',
]

export const GOAL_CATEGORIES = PEPTIDE_CATEGORIES

export function findPeptide(name: string): PeptideKnowledge | undefined {
  const n = name.toLowerCase()
  return PEPTIDE_KNOWLEDGE.find(p => p.name.toLowerCase().includes(n))
}

export function searchPeptides(query: string): PeptideKnowledge[] {
  if (!query.trim()) return PEPTIDE_KNOWLEDGE
  const q = query.toLowerCase()
  return PEPTIDE_KNOWLEDGE.filter(p =>
    p.name.toLowerCase().includes(q) ||
    p.whatItDoes.toLowerCase().includes(q) ||
    p.keyEffects.toLowerCase().includes(q) ||
    p.goalCategory.toLowerCase().includes(q)
  )
}

export function getPeptidesByCategory(category: string): PeptideKnowledge[] {
  return PEPTIDE_KNOWLEDGE.filter(p => p.goalCategories.includes(category))
}
